          "citation": "Chapter 1, p. 27"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "dom7",
      "function_role": "related-dominant-substitution",
      "narrative": "The four dominant 7th chords derived from the same diminished triad are interchangeable when resolving V7-I. Harris illustrates with D7-Gmaj7: F7, Ab7, and B7 are also related to F# diminished and make interesting voicings when played against D in the bass. Chapter 4, p. 83.",
      "source_principle_ids": [
        "barry-harris:jazz-workshop:diminished-scale-harmony"
      ],
      "source_work_id": "jazz-workshop",
      "references": [
