      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7",
      "function_role": "bass-continuity-with-related-dominants",
      "narrative": "When substituting related dominants over a V7-I resolution, Harris prescribes keeping the original dominant root in the bass while shifting the upper voicing to the related dominant chord. The D7-Gmaj7 example shows F7, Ab7, and B7 played against D in the bass, preserving bass-line identity while varying harmonic color. Chapter 4, p. 83.",
      "source_principle_ids": [
        "barry-harris:jazz-workshop:diminished-scale-harmony"
      ],
      "source_work_id": "jazz-workshop",
      "references": [
        {
          "source": "jazz-workshop",
          "citation": "Chapter 4, p. 83"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "g",
      "granularity_name": "voice-leading"
    },
    {
      "chord_quality": "dom7",
      "function_role": "three-arpeggio-positions",
      "narrative": "For the dominant 7th scale, Harris specifies exactly three important arpeggios: on the tonic, the 5th, and the 7th. These are the only arpeggio positions the student prioritizes in practice. Chapter 1, p. 13.",
      "source_principle_ids": [
        "barry-harris:jazz-workshop:half-step-improvisation"
      ],
      "source_work_id": "jazz-workshop",
      "references": [
        {
