        }
      ],
      "provenance": "extracted",
      "granularity_level": "i",
      "granularity_name": "other"
    },
    {
      "chord_quality": "dom7",
      "function_role": "half-step-bebop-vocabulary",
      "narrative": "The dominant 7th scale has its own set of scale-degree-specific rules for inserting chromatic half-steps in descending phrases to generate bebop vocabulary. Half-steps typify the language of the bebop player and are an endless source of improvisational ideas. Chapter 1, p. 17.",
      "source_principle_ids": [
        "barry-harris:jazz-workshop:half-step-improvisation"
      ],
      "source_work_id": "jazz-workshop",
