      "granularity_name": "other"
    },
    {
      "chord_quality": "dom7",
      "function_role": "key-specific-diminished-application",
      "narrative": "When applying diminished extensions over dominant 7th chords in minor keys, Harris specifies the diminished chord by key: C7 in F minor uses E-diminished; G7 in C minor uses B-diminished. The related diminished selection is both key- and chord-specific. Chapter 5, p. 93.",
      "source_principle_ids": [
        "barry-harris:jazz-workshop:diminished-scale-harmony"
      ],
