    },
    {
      "chord_quality": "maj6",
      "function_role": "harmonic-family-membership",
      "narrative": "Harris assigns the major 6th chord as the primary identity of the major 6 diminished scale family. It is the foundational chord from which all major-function voicings derive via 'a scale for chording, and a method of assigning virtually any chord to one of two scales\u2014the major 6 diminished and the minor 6 diminished.' Chapter 3, p. 66.",
      "source_principle_ids": [
        "barry-harris:jazz-workshop:diminished-scale-harmony"
      ],
      "source_work_id": "jazz-workshop",
      "references": [
        {
          "source": "jazz-workshop",
          "citation": "Chapter 3, p. 66"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "maj6",
      "function_role": "scale-for-chording-source",
      "narrative": "The C6 diminished scale\u2014built on the major 6th chord\u2014contains three interlocking diminished chords providing its internal architecture: the C and A belong to one diminished, the E and G to a second, and the B diminished chord provides the other four notes. All voicings within a major-function passage are drawn from this scale. Chapter 3, p. 67.",
      "source_principle_ids": [
        "barry-harris:jazz-workshop:diminished-scale-harmony"
      ],
      "source_work_id": "jazz-workshop",
      "references": [
        {
