          "citation": "Chapter 3, p. 67"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "maj6",
      "function_role": "voice-leading-into-next-chord",
      "narrative": "When moving between major-6-scale voicings, Harris's governing rule applies directly: remember to move each note to the next note of the scale. Each voice in a maj6-family voicing steps to its adjacent neighbor in the major 6 diminished scale, creating smooth voice motion. Chapter 3, p. 71.",
      "source_principle_ids": [
        "barry-harris:jazz-workshop:diminished-scale-harmony"
      ],
      "source_work_id": "jazz-workshop",
